// Writer writes the records of one file, walking the automaton this descriptor
// carries in the other direction.
//
// Its caller names a record and supplies that record's values. It narrows to
// the transitions leaving the state it is in that admit such a record and whose
// guards all hold, evaluates their predicates in the order the state carries
// them, and takes the first that carries no predicate or whose predicate matches
// the bytes it is about to emit. A record satisfying none is reported rather
// than emitted: refusing where the mistake was made costs one diagnostic, and
// emitting costs a file somebody has to read before anyone finds out.
//
// Nothing is buffered beyond the record in hand. A count in a header is never
// back-filled from the records behind it, because holding a group to count it
// gives up exactly the streaming this type exists to have — and because a
// writer that has emitted a record cannot reach back into a stream it does not
// own.
type Writer struct {
	dst io.Writer

	// cw lays out the record in hand, and is the only encoder this writer
	// builds: a predicate is evaluated against the bytes that are about to go
	// out, so a record exists as bytes before the transition carrying it is
	// chosen, and the method emitting a record rewinds this onto it rather
	// than constructing one over it. The buffer those bytes accumulate in is
	// this encoder's own — [codec.Writer.Bytes] is where they are read back —
	// and it is kept at its capacity across every rewind, along with everything
	// the encoding derives. That is why the encoding is not kept beside it:
	// codec.Writer carries it, and one that could be swapped under a half-laid
	// record is what codec refuses to allow.
	cw *codec.Writer

	// lits is every literal this writer compares — a transition's predicate, and a
	// guard over a bytes register — as a file under its encoding spells it. It is
	// re-expressed once, when the writer is built, and never per record; under the
	// descriptor's own encoding it is the literals the descriptor resolved. See
	// literals.go.
	lits *literals

	// state is where in the automaton the write is, numbered as [Reader.state] is.
	state int

	// ordinal is how many records have been written, so that a diagnostic can
	// say where.
	ordinal int

	// The register file. There is one for the whole write, a register holds what the
	// most recent binding put in it, and nothing saves or restores one — so the
	// value in force is the one from the nearest preceding record that bound it,
	// along the path actually taken.
	//
	// Each carries whether anything has bound it, because reading a register
	// nothing has written is a malformed descriptor rather than a zero: a consumer
	// MUST NOT supply a zero, an empty byte string or the value of any other
	// register. See docs/ir/SPEC.md, "The automaton remembers, in registers".
	register39      int64
	register39Bound bool
}

// NewWriter writes records into w under [Encoding], the layout's own encoding,
// with each of opts replacing the axis it names. Handed no option, it writes
// the file the layout describes:
//
//	w, err := NewWriter(out)
//
// A copy of that file converted to another character set holds the same
// records, and is written by naming the axes the conversion rewrote:
//
//	w, err := NewWriter(out, WithCharset(codec.ASCII()), WithSignConvention(codec.SignTranslatedEBCDIC))
//
// Each option is validated here, before any record is written: a value codec
// has no member for is refused with the error codec reports for its axis. The
// binary width staircase is not among them — every offset this package
// slices at was computed under the descriptor's, and no [Option] replaces it.
//
// Every literal this package compares a field against is re-expressed here,
// once, as a file under the encoding the options leave spells it; an item
// whose charset is none carries bytes, and its literals never move. A literal
// no file under that encoding can hold is refused here rather than at the
// record that would first have needed it, and the refusal names the literal,
// the item, the record and the axis: it is about the layout and the options,
// and not about the file. See literals.go.
//
// It is the same re-expression [NewReader] makes, so the record this writer
// refuses to emit is the record a reader handed the same options would route
// elsewhere.
func NewWriter(w io.Writer, opts ...Option) (*Writer, error) {
	if w == nil {
		return nil, codec.ErrNilWriter
	}

	enc := encodingWith(opts)

	// The one encoder this writer builds, over a buffer of no bytes until the
	// first record is laid into it. Construction is what validates the
	// encoding, and every option with it: it reports the same error for the
	// same axis that enc.Validate does, so nothing is checked twice here.
	cw, err := codec.NewBytesWriter(nil, enc)
	if err != nil {
		return nil, err
	}

	// Every literal this package compares, as a file under enc spells it. One
	// with no spelling there is refused here, before any record is written: it is a
	// property of the layout and of enc, and no file enc describes could hold it.
	lits, err := literalsFor(enc)
	if err != nil {
		return nil, err
	}

	return &Writer{
		dst:   w,
		cw:    cw,
		lits:  lits,
		state: 0,
	}, nil
}

// Write emits one record.
//
// A value that is not one of this file's record types is reported rather than
// emitted: no transition admits a record the descriptor does not carry, and
// [Record] is satisfied by anything codec can encode.
func (w *Writer) Write(rec Record) error {
	switch v := rec.(type) {
	case *CreditPosting:
		return w.writeCreditPosting(v)
	case *DebitPosting:
		return w.writeDebitPosting(v)
	case *LedgerHeader:
		return w.writeLedgerHeader(v)
	case *LedgerTrailer:
		return w.writeLedgerTrailer(v)
	default:
		return fmt.Errorf("record %d: this file's records are POSTING-RECORD, POSTING-RECORD, LEDGER-HEADER and LEDGER-TRAILER, and a %T is none of them", w.ordinal+1, rec)
	}
}

// Close ends the file, and reports a state that does not accept — or whose
// acceptance guards do not all hold — rather than closing it.
//
// A group that promised four details and was given three is caught here. It is
// the reader's truncation rule from the other side, and a writer skipping the
// check emits the truncated file its reader complains about one build later.
//
// It does not close the io.Writer it was handed, which belongs to the caller.
func (w *Writer) Close() error {
	switch w.state {
	case 4:
		return nil
	default:
		return fmt.Errorf("the file is closed after %d records and the layout describes a record to come", w.ordinal)
	}
}

// writeCreditPosting emits one POSTING-RECORD.
//
// The record is laid out first and the transition is chosen against those
// bytes, because what a predicate tests is what is about to be emitted.
func (w *Writer) writeCreditPosting(rec *CreditPosting) error {
	// The encoder is rewound onto the buffer it filled for the record before
	// this one rather than built over a fresh one. A rewind keeps everything
	// the encoding derives and the capacity that buffer reached, and it puts
	// the offset back to zero, so every offset codec reports is counted from
	// the start of this record rather than from the start of the file.
	w.cw.Reset(w.cw.Bytes())

	if err := rec.MarshalCOBOL(w.cw); err != nil {
		return fmt.Errorf("writing record %d: %w", w.ordinal+1, err)
	}

	// The record's bytes, which are the encoder's own buffer and are valid
	// until the rewind above happens again. Nothing below holds them past
	// that: a predicate reads them, the framing writes them out, and a
	// binding taking a register's bytes out of them copies.
	raw := w.cw.Bytes()

	var excluded string

	switch w.state {
	case 1: // the state the descriptor carries as node 41
		// Transition 3 of that state.
		if !w.register39Bound {
			return w.unbound(39)
		}

		if w.register39 > 0 {
			if w.lits.matches4At12(raw) {
				if err := w.emit(raw); err != nil {
					return err
				}

				if !w.register39Bound {
					return w.unbound(39)
				}

				if w.register39 <= 0 {
					return fmt.Errorf("record %d takes one off the register the descriptor carries as node 39, which is already at zero: a counter that would run below zero is a bug in whatever produced this descriptor", w.ordinal)
				}

				w.register39--

				w.state = 3
				w.ordinal++

				return nil
			}
		} else if excluded == "" && w.lits.matches4At12(raw) {
			excluded = fmt.Sprintf("a guard excluded the transition that would have taken it, which is taken only where the register the descriptor carries as node 39 is greater than zero; node 39 holds %d", w.register39)
		}
	case 2: // the state the descriptor carries as node 42
		// Transition 3 of that state.
		if !w.register39Bound {
			return w.unbound(39)
		}

		if w.register39 > 0 {
			if w.lits.matches4At12(raw) {
				if err := w.emit(raw); err != nil {
					return err
				}

				if !w.register39Bound {
					return w.unbound(39)
				}

				if w.register39 <= 0 {
					return fmt.Errorf("record %d takes one off the register the descriptor carries as node 39, which is already at zero: a counter that would run below zero is a bug in whatever produced this descriptor", w.ordinal)
				}

				w.register39--

				w.state = 3
				w.ordinal++

				return nil
			}
		} else if excluded == "" && w.lits.matches4At12(raw) {
			excluded = fmt.Sprintf("a guard excluded the transition that would have taken it, which is taken only where the register the descriptor carries as node 39 is greater than zero; node 39 holds %d", w.register39)
		}
	case 3: // the state the descriptor carries as node 43
		// Transition 3 of that state.
		if !w.register39Bound {
			return w.unbound(39)
		}

		if w.register39 > 0 {
			if w.lits.matches4At12(raw) {
				if err := w.emit(raw); err != nil {
					return err
				}

				if !w.register39Bound {
					return w.unbound(39)
				}

				if w.register39 <= 0 {
					return fmt.Errorf("record %d takes one off the register the descriptor carries as node 39, which is already at zero: a counter that would run below zero is a bug in whatever produced this descriptor", w.ordinal)
				}

				w.register39--

				w.state = 3
				w.ordinal++

				return nil
			}
		} else if excluded == "" && w.lits.matches4At12(raw) {
			excluded = fmt.Sprintf("a guard excluded the transition that would have taken it, which is taken only where the register the descriptor carries as node 39 is greater than zero; node 39 holds %d", w.register39)
		}
	}

	return w.refuse("POSTING-RECORD", excluded)
}

