// writeLedgerHeader emits one LEDGER-HEADER.
//
// The record is laid out first and the transition is chosen against those
// bytes, because what a predicate tests is what is about to be emitted.
func (w *Writer) writeLedgerHeader(rec *LedgerHeader) error {
	// The encoder is rewound onto the buffer it filled for the record before
	// this one rather than built over a fresh one. A rewind keeps everything
	// the encoding derives and the capacity that buffer reached, and it puts
	// the offset back to zero, so every offset codec reports is counted from
	// the start of this record rather than from the start of the file.
	w.cw.Reset(w.cw.Bytes())

	if err := rec.MarshalCOBOL(w.cw); err != nil {
		return fmt.Errorf("writing record %d: %w", w.ordinal+1, err)
	}

	// The record's bytes, which are the encoder's own buffer and are valid
	// until the rewind above happens again. Nothing below holds them past
	// that: a predicate reads them, the framing writes them out, and a
	// binding taking a register's bytes out of them copies.
	raw := w.cw.Bytes()

	switch w.state {
	case 0: // the state the descriptor carries as node 40
		// Transition 1 of that state.
		if w.lits.matches1At0(raw) {
			if err := w.emit(raw); err != nil {
				return err
			}

			w.register39 = int64(rec.HdrCount)
			w.register39Bound = true

			w.state = 1
			w.ordinal++

			return nil
		}
	}

	return w.refuse("LEDGER-HEADER", "")
}

// writeLedgerTrailer emits one LEDGER-TRAILER.
//
// The record is laid out first and the transition is chosen against those
// bytes, because what a predicate tests is what is about to be emitted.
func (w *Writer) writeLedgerTrailer(rec *LedgerTrailer) error {
	// The encoder is rewound onto the buffer it filled for the record before
	// this one rather than built over a fresh one. A rewind keeps everything
	// the encoding derives and the capacity that buffer reached, and it puts
	// the offset back to zero, so every offset codec reports is counted from
	// the start of this record rather than from the start of the file.
	w.cw.Reset(w.cw.Bytes())

	if err := rec.MarshalCOBOL(w.cw); err != nil {
		return fmt.Errorf("writing record %d: %w", w.ordinal+1, err)
	}

	// The record's bytes, which are the encoder's own buffer and are valid
	// until the rewind above happens again. Nothing below holds them past
	// that: a predicate reads them, the framing writes them out, and a
	// binding taking a register's bytes out of them copies.
	raw := w.cw.Bytes()

	var excluded string

	switch w.state {
	case 1: // the state the descriptor carries as node 41
		// Transition 1 of that state.
		if !w.register39Bound {
			return w.unbound(39)
		}

		if w.register39 == 0 {
			if w.lits.matches2At0(raw) {
				if err := w.emit(raw); err != nil {
					return err
				}

				w.state = 4
				w.ordinal++

				return nil
			}
		} else if excluded == "" && w.lits.matches2At0(raw) {
			excluded = fmt.Sprintf("a guard excluded the transition that would have taken it, which is taken only where the register the descriptor carries as node 39 is 0; node 39 holds %d", w.register39)
		}
	case 2: // the state the descriptor carries as node 42
		// Transition 1 of that state.
		if !w.register39Bound {
			return w.unbound(39)
		}

		if w.register39 == 0 {
			if w.lits.matches2At0(raw) {
				if err := w.emit(raw); err != nil {
					return err
				}

				w.state = 4
				w.ordinal++

				return nil
			}
		} else if excluded == "" && w.lits.matches2At0(raw) {
			excluded = fmt.Sprintf("a guard excluded the transition that would have taken it, which is taken only where the register the descriptor carries as node 39 is 0; node 39 holds %d", w.register39)
		}
	case 3: // the state the descriptor carries as node 43
		// Transition 1 of that state.
		if !w.register39Bound {
			return w.unbound(39)
		}

		if w.register39 == 0 {
			if w.lits.matches2At0(raw) {
				if err := w.emit(raw); err != nil {
					return err
				}

				w.state = 4
				w.ordinal++

				return nil
			}
		} else if excluded == "" && w.lits.matches2At0(raw) {
			excluded = fmt.Sprintf("a guard excluded the transition that would have taken it, which is taken only where the register the descriptor carries as node 39 is 0; node 39 holds %d", w.register39)
		}
	}

	return w.refuse("LEDGER-TRAILER", excluded)
}

// refuse is what a writer says when no transition leaving the state it is in
// took the record it was asked to write.
//
// Two things bring a caller here and the message covers both, because the
// writer's walk is narrowed before any predicate runs: the state may admit no
// record of this type at all, which is a record written out of order, or it may
// admit one and be selected by a predicate this record's values do not satisfy.
//
// Either way the record does not belong at this point in the file with the
// values it has, and the value a predicate tests is the caller's: a writer
// checks it and reports it when it is wrong rather than deriving one that would
// satisfy the test and storing it into the field.
func (w *Writer) refuse(record string, excluded string) error {
	if excluded != "" {
		return fmt.Errorf("record %d is a %s and does not belong here: %s", w.ordinal+1, record, excluded)
	}

	return fmt.Errorf("record %d is a %s and no transition leaving the state the automaton is in takes it: that state admits no %s here, or one it admits is selected by a predicate this record's values do not satisfy. It is reported rather than emitted", w.ordinal+1, record, record)
}

// unbound is a register read before anything wrote it, which is a malformed
// descriptor rather than a zero.
func (w *Writer) unbound(node int) error {
	return fmt.Errorf("record %d reads the register the descriptor carries as node %d, and no transition taken before it bound one", w.ordinal+1, node)
}

// emit writes one record's bytes with this file's framing around them.
//
// The record descriptor word DFSMS defines stands in front of each record and
// states the record's length including itself.
func (w *Writer) emit(raw []byte) error {
	stated := len(raw) + 4
	if stated > 0xFFFF {
		return fmt.Errorf("record %d is %d bytes and a record descriptor word states a length of two bytes", w.ordinal+1, len(raw))
	}

	if _, err := w.dst.Write([]byte{byte(stated >> 8), byte(stated), 0, 0}); err != nil {
		return err
	}

	_, err := w.dst.Write(raw)

	return err
}
